async fn v2_create_with_staging_entry_links_and_processes_it() {
    let (
        _app,
        client,
        token,
        merchant_id,
        profile_id,
        source_account_id,
        target_account_id,
        rule_id,
    ) = setup_test_environment().await;

    let transaction = mismatched_transaction(
